export const inject = ['tools']

export function apply(ctx) {
  ctx.tool({
    name: 'my_plugin_ping',
    description: '示例工具：回显一段文本',
    inputSchema: { type: 'object', properties: { text: { type: 'string' } }, required: ['text'] },
    handler: async (input) => ({ ok: true, value: { echo: String(input?.text ?? '') } }),
  })
  ctx.log.info('插件已激活')
}

